import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
const ROOT = resolve(__dirname, "..");
function read(p:string){ return readFileSync(resolve(ROOT,p),"utf8"); }

describe("massive 42.2 - hype-features 30 new fich (42.73-43.02)", () => {
  const src = read("docs/hype-features.md");
  it("contains 30 new fich 42.73-43.02", () => {
    expect(src).toContain("42.73");
    expect(src).toContain("42.80");
    expect(src).toContain("42.90");
    expect(src).toContain("43.00");
    expect(src).toContain("43.02");
    expect((src.match(/Bratukha-Ficha/g)||[]).length).toBeGreaterThanOrEqual(86);
  });
  it("each new ficha has required blocks", () => {
    for(let n=73;n<=99;n++){
      expect(src).toContain(`42.${n}`);
      expect(src).toContain(`magnum-42.${n}`);
      expect(src).toContain(`Hype42_${n}`);
    }
    for(let n=0;n<=2;n++){
      const pad = String(n).padStart(2,'0');
      expect(src).toContain(`43.${pad}`);
    }
    expect(src).toContain("PRESAVE https://music.thefence.me/psmagnum");
    expect(src).toContain("krinzha ne sushchestvuet");
  });
  it("hype file is long enough", () => {
    const lines = src.split("\n").length;
    expect(lines).toBeGreaterThanOrEqual(4400);
  });
});

describe("massive 42.2 - RecapsPage 20 new Freakland cards 131-150", () => {
  const src = read("src/pages/RecapsPage.tsx");
  it("contains 150 freakland gen3 cards", () => {
    const count = (src.match(/recap-freakland-gen3/g)||[]).length;
    expect(count).toBeGreaterThanOrEqual(150);
  });
  it("new cards 131-150 exist with transcript false", () => {
    for(let i=131;i<=150;i++){
      expect(src).toContain(`recap-freakland-gen3-${String(i).padStart(3,'0')}`);
    }
    expect((src.match(/transcript: false/g)||[]).length).toBeGreaterThanOrEqual(155);
    expect(src).toContain('transkript skoro');
  });
  it("RecapsPage respects Freakland tag and honest paragraphs", () => {
    expect(src).toContain('tag: "Freakland"');
    expect(src).toContain('Pochemu v MAGNUM');
    expect(src).toContain('Chestno: transkript');
  });
  it("RecapsPage is long enough", () => {
    const lines = src.split("\n").length;
    expect(lines).toBeGreaterThanOrEqual(3350);
  });
});

